        int relatives; cin >> relatives;
        vector<int> addresses(relatives);
        int addressSum=0;
        for(int &address:addresses) { cin >> address; addressSum+=address; }
        sort(addresses.begin(),addresses.end());
        int result=addresses[relatives/2];
        int distanceSum=0;
        for(int address:addresses) distanceSum+=abs(address-result);
        cout << distanceSum << '\n';
    }
}
